    ('ef73ab96-3f35-4e88-8586-2740f5cdae65'::uuid, 'site_type', 'Rock relief/carving', 'Inscription', 'fields-wd1-2026-09-26b-s011:ef73ab96-3f35-4e88-8586-2740f5cdae65:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Rock relief/carving'' -> ''Inscription''', '[{"source": "https://en.wikipedia.org/wiki/Shahbaz_Garhi", "url": "https://en.wikipedia.org/wiki/Shahbaz_Garhi", "quote": "The town is the location of ancient Indian rock-inscriptions", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/shahbazgarhi/", "url": "https://www.livius.org/articles/place/shahbazgarhi/", "quote": "The inscriptions were written in the kharoshthi-alphabet, which was, during the Persian occupation of the Punjab, derived from the Aramaic script.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0018)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is not a village but the Ashoka rock edicts, described as ancient rock inscriptions in Kharosthi cut into two boulders; the more specific canonical type is Inscription rather than the generic Rock relief/carving.", "value_page": null}]'::jsonb),
    ('efaa3f7a-4a10-4d40-84b7-e4a1a49e47c6'::uuid, 'site_type', 'Temple complex', 'City/town/settlement', 'fields-wd1-2026-09-26b-s011:efaa3f7a-4a10-4d40-84b7-e4a1a49e47c6:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Temple complex'' -> ''City/town/settlement''', '[{"source": "https://en.wikipedia.org/wiki/Pikillaqta", "url": "https://en.wikipedia.org/wiki/Pikillaqta", "quote": "Type Settlement", "outcome": "found"}, {"source": "https://www.cuscoperu.com/en/travel/south-valley-of-cusco/archaeological-centers/piquillacta/", "url": "https://www.cuscoperu.com/en/travel/south-valley-of-cusco/archaeological-centers/piquillacta/", "quote": "It is an ancient planned city, built mainly with stone, mud, and mortar, known for its geometric design, orderly streets, and numerous enclosures.", "outcome": "found"}, {"source": "https://www.culturacusco.gob.pe/parques/pikillaqta/", "url": "https://www.culturacusco.gob.pe/parques/pikillaqta/", "quote": "Los vestigios arqueológicos de Pikillaqta, pertenecientes a la cultura Wari, evidencian una urbe planificada con gran armonía.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "CONFLICT", "reasoning": "Pikillaqta is a planned Wari city/administrative settlement with some 700 buildings, not a temple complex: Wikipedia types it as a settlement, CuscoPeru calls it an ancient planned city and the Cusco culture directorate an ''urbe planificada''.", "value_page": null}]'::jsonb),
