    ('efe2bc83-83cc-4393-b725-a18543dc9d5f'::uuid, 'period_start', '-3000', '-3800', 'fields-wd1-2026-09-26b-s011:efe2bc83-83cc-4393-b725-a18543dc9d5f:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-3000'' -> ''-3800''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=12111", "url": "https://www.megalithic.co.uk/article.php?sid=12111", "quote": "Menga is the oldest of the great dolmens in Iberia (approximately 3800 to 3600 BCE).", "outcome": "found"}, {"source": "https://culturalheritageonline.com/places/dolmens-of-antequera/", "url": "https://culturalheritageonline.com/places/dolmens-of-antequera/", "quote": "comprises three monuments built during the Chalcolithic (Copper Age) between approximately 3800 and 3000 BC", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Dolmen_of_Menga", "url": "https://en.wikipedia.org/wiki/Dolmen_of_Menga", "quote": "dating from the Neolithic period around 3750–3650 BCE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "MISSING", "reasoning": "The ensemble''s oldest monument, the Dolmen of Menga, was built c. 3800-3600 BC (Megalithic Portal, Cultural Heritage Online, Wikipedia), so the site''s start lies in the 4500-3000 BC bucket, not in 3000-1500 BC.", "value_page": null}]'::jsonb),
