    ('f064d736-e58e-4505-b634-b5f18052e293'::uuid, 'period_start', '-3000', '-1100', 'fields-wd1-2026-09-26b-s011:f064d736-e58e-4505-b634-b5f18052e293:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-3000'' -> ''-1100''', '[{"source": "https://en.wikipedia.org/wiki/Salamis,_Cyprus", "url": "https://en.wikipedia.org/wiki/Salamis,_Cyprus", "quote": "In the 11th century BC, the town was confined to a rather small area around the harbour but soon expanded westwards to occupy the area, which today is covered by forest.", "outcome": "found"}, {"source": "https://www.ancientcyprus.com/sites/salamis", "url": "https://www.ancientcyprus.com/sites/salamis", "quote": "However, the discovery of a chamber tomb dating to the Cypro-Geometric period (11th century BC) south of the later Temple of Zeus Olympios does confirm the existence of a well-established seaside town in this area at that early date.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0020)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia (earliest finds in the 11th century BC, the town then confined to the harbour area) and ancientcyprus.com (an 11th-century BC chamber tomb confirming the seaside town, Salamis replacing Enkomi in Late Cypriot IIIB) both put the start of Salamis in the 11th century BC, i.e. the 1500 - 500 BC bucket, not 3000 - 1500 BC; the earlier Bronze Age occupation belongs to Enkomi, a separate site.", "value_page": null}]'::jsonb),
