    ('f0a1dcca-8eb4-4c5a-b2ef-d90160d13d79'::uuid, 'period_start', '-3000', '-100', 'fields-wd1-2026-09-26b-s011:f0a1dcca-8eb4-4c5a-b2ef-d90160d13d79:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-3000'' -> ''-100''', '[{"source": "https://archeologie.culture.gouv.fr/afghanistan/en/a-propos/ainak", "url": "https://archeologie.culture.gouv.fr/afghanistan/en/a-propos/ainak", "quote": "Probably from the Bronze Age and certainly from the 1st century BCE, the mining of ore was carried out alongside the transformation and metalworking of copper.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Mes_Aynak", "url": "https://en.wikipedia.org/wiki/Mes_Aynak", "quote": "Mes Aynak also holds the remains of prior civilizations likely going as far back as the 3rd century BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "The French Ministry of Culture/DAFA page attests activity at the site certainly from the 1st century BCE (Bronze Age mining only ''probably''), and Wikipedia puts the earliest remains likely in the 3rd century BC; the secure start lies in the 500 BC-1 AD bucket, not the stored 3000-1500 BC one.", "value_page": null}]'::jsonb),
    ('f0a1dcca-8eb4-4c5a-b2ef-d90160d13d79'::uuid, 'site_type', 'Temple complex', 'Monastery', 'fields-wd1-2026-09-26b-s011:f0a1dcca-8eb4-4c5a-b2ef-d90160d13d79:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Temple complex'' -> ''Monastery''', '[{"source": "https://en.wikipedia.org/wiki/Mes_Aynak", "url": "https://en.wikipedia.org/wiki/Mes_Aynak", "quote": "Remains of a Buddhist monastery at Mes Aynak", "outcome": "found"}, {"source": "https://archeologie.culture.gouv.fr/afghanistan/en/a-propos/ainak", "url": "https://archeologie.culture.gouv.fr/afghanistan/en/a-propos/ainak", "quote": "Buddhist monasteries, generally fortified, were built around the mining area", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0001)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe Mes Aynak as a Buddhist monastic complex (several fortified monasteries with stupas) around an ancient copper mine; they do not call it a temple complex, and Monastery is the most specific canonical type for its principal monuments.", "value_page": null}]'::jsonb),
