    ('f0bcab22-b5ea-43e1-ace1-c9adc5d6e0db'::uuid, 'period_start', '-500', '101', 'fields-wd1-2026-09-26b-s011:f0bcab22-b5ea-43e1-ace1-c9adc5d6e0db:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-500'' -> ''101''', '[{"source": "https://www.carianmonuments.com/mylasa/", "url": "https://www.carianmonuments.com/mylasa/", "quote": "Stylistic analysis of the deep drilling and geometric gaps in the acanthus leaves suggests the monument dates to the late 2nd century CE.", "outcome": "found"}, {"source": "https://www.milas.gov.tr/baltali-kapii", "url": "https://www.milas.gov.tr/baltali-kapii", "quote": "MS. 2.yüzyıla tarihlenmekte.", "outcome": "found"}, {"source": "https://www.persee.fr/doc/anata_1018-1946_2009_num_17_1_1284", "url": "https://www.persee.fr/doc/anata_1018-1946_2009_num_17_1_1284", "quote": "Rumscheid dagegen halt beides fiir gleichzeitig und schlàgt ein Datum im 2. Jh. n. Chr. vor", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "replace", "status": "MISSING", "reasoning": "The specialist study (Kızıl 2009 in Anatolia Antiqua, following Rumscheid 1996) dates gate and aqueduct together to the 2nd century AD, and carianmonuments.com and the Milas district governorship date the gate to the 2nd century AD; the older end-of-1st-century-BC dating from building style is superseded, so the start moves to 101 (bucket 1 - 500 AD).", "value_page": null}]'::jsonb),
