    ('f23a31c3-6833-4df6-8583-3b3930b5a74f'::uuid, 'site_type', 'Residence/villa/farmhouse', 'Bath', 'fields-wd1-2026-09-26b-s011:f23a31c3-6833-4df6-8583-3b3930b5a74f:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Residence/villa/farmhouse'' -> ''Bath''', '[{"source": "https://britishlistedbuildings.co.uk/101376085-39-bridge-street-chester-city-ward", "url": "https://britishlistedbuildings.co.uk/101376085-39-bridge-street-chester-city-ward", "quote": "the undercroft was built over part of a C2 AD Roman bath house", "outcome": "found"}, {"source": "https://www.historyhit.com/locations/39-bridge-street/", "url": "https://www.historyhit.com/locations/39-bridge-street/", "quote": "The system would have been a part of the legionary baths", "outcome": "found"}, {"source": "http://www.chestertourist.com/underground.htm", "url": "http://www.chestertourist.com/underground.htm", "quote": "These Roman remains are located on Bridge Street in the basement of Spud-U-Like. They are part of the legionary baths.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0008)", "decision": "replace", "status": "MISSING", "reasoning": "The Historic England listing text (mirrored on British Listed Buildings), History Hit and Chester Tourist all describe the ancient part of 39 Bridge Street, Chester, as part of the Roman legionary bath house with its hypocaust in the cellar; no source calls it a residence, villa or farmhouse, so the stored type is wrong and Bath fits.", "value_page": null}]'::jsonb),
