    ('f26676eb-8ab7-4032-86de-b28e992373f8'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s011:f26676eb-8ab7-4032-86de-b28e992373f8:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0126)", "decision": "clear", "status": "MISSING", "reasoning": "English Wikipedia says only that the town''s area was settled in the Stone Age, Neolithic, Bronze Age and Roman era, without dates, and Serbian Wikipedia dates only its oldest Roman remains, vaguely, to the beginning of the Christian era; since the site''s first occupation is prehistoric and undated, no start year can be quoted from two sources.", "value_page": null}]'::jsonb),
