    ('f29afd0d-6fb8-4405-bee8-c1b17a6989e3'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s011:f29afd0d-6fb8-4405-bee8-c1b17a6989e3:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "clear", "status": "CONFLICT", "reasoning": "Levi (2002) says San Estevan was settled in the Middle Preclassic and Rosenswig & Kennett (2008) found Middle through Late Formative deposits in the site centre, but neither gives a year; only Wikipedia prints a year (occupied during the Formative, 800 BC - AD 300), and Wikidata''s -300 is the start of its Late Formative role as a political centre, not its first occupation, so no two independent sources date the start and the field is emptied.", "value_page": null}]'::jsonb),
    ('f31b4aea-5e0d-42f8-80f0-60fcf2f3c37f'::uuid, 'period_name', '4500 - 3000 BC', '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s011:f31b4aea-5e0d-42f8-80f0-60fcf2f3c37f:period_name', 'fields-wd1-2026-09-26b-s011 (wd1-derive-period-name): period_start 1045 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1045) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('f31b4aea-5e0d-42f8-80f0-60fcf2f3c37f'::uuid, 'period_start', '-4500', '1045', 'fields-wd1-2026-09-26b-s011:f31b4aea-5e0d-42f8-80f0-60fcf2f3c37f:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-4500'' -> ''1045''', '[{"source": "https://heritage.suffolk.gov.uk/Monument/MSF5961", "url": "https://heritage.suffolk.gov.uk/Monument/MSF5961", "quote": "Founded by ''earl'' Aelfric son of Wihtgar (also see BRD 123) circa 1045 Mentioned in Domesday, with reference to original grant", "outcome": "found"}, {"source": "https://opendomesday.org/place/TL7645/clare/", "url": "https://opendomesday.org/place/TL7645/clare/", "quote": "It had a recorded population of 128 households in 1086, putting it in the largest 20% of settlements recorded in Domesday.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Clare,_Suffolk", "url": "https://en.wikipedia.org/wiki/Clare,_Suffolk", "quote": "The name first appears in the Domesday Book of 1086 as ''Clara''.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "MISSING", "reasoning": "The prehistoric finds around Clare are isolated objects and the Iron Age camp is undated, so nothing supports -4500; the town''s securely attested history begins with the collegiate church of St John founded at Clare circa 1045 (Suffolk HER) and its record in Domesday Book (Open Domesday, Wikipedia), all in the 1000 - 1500 AD bucket.", "value_page": null}]'::jsonb),
