    ('f69cf72f-d7b2-48d8-996d-82e19c289eee'::uuid, 'period_start', '-500', '-1100', 'fields-wd1-2026-09-26b-s011:f69cf72f-d7b2-48d8-996d-82e19c289eee:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-500'' -> ''-1100''', '[{"source": "http://www.whatson-northcyprus.com/interest/lefke/soli.htm", "url": "http://www.whatson-northcyprus.com/interest/lefke/soli.htm", "quote": "Its history can be dated back to the 11th century BC.", "outcome": "found"}, {"source": "https://www.alaturka.info/en/cyprus/kyrenia/3301-history-of-the-roman-city-of-soli-in-cyprus", "url": "https://www.alaturka.info/en/cyprus/kyrenia/3301-history-of-the-roman-city-of-soli-in-cyprus", "quote": "a city whose traces can be followed back to the 11th century BC.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Soloi_(Zypern)", "url": "https://de.wikipedia.org/wiki/Soloi_(Zypern)", "quote": "Die Ausgrabungsbefunde lassen erkennen, dass die Anfänge von Soloi in die Zeit um 1100 v. Chr., den ungefähren Beginn der zypro-geometrischen Epoche, zurückreichen.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavation evidence reported by German Wikipedia puts the beginnings of Soloi around 1100 BC, and two independent travel/heritage guides trace the site back to the 11th century BC; the city is also named on the Esarhaddon prism of 673/672 BC. The attested start therefore lies in 1500 - 500 BC, not in the stored 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
