    ('f70384d7-00ec-45ba-b086-bf1aba816f84'::uuid, 'site_type', 'Archaeological site', 'City', 'fields-wd1-2026-09-26b-s011:f70384d7-00ec-45ba-b086-bf1aba816f84:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Archaeological site'' -> ''City''', '[{"source": "https://perseus-aa.github.io/items/aa_3893.html", "url": "https://perseus-aa.github.io/items/aa_3893.html", "quote": "The city was founded in the Geometric period and was most prosperous in the 8th - 6th centuries B.C.", "outcome": "found"}, {"source": "https://www.discovercrete.com/places-to-go/ancient-dreros", "url": "https://www.discovercrete.com/places-to-go/ancient-dreros", "quote": "Ancient Dreros is regarded as a significant ancient city of Crete.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "replace", "status": "CONFLICT", "reasoning": "Perseus and Discover Crete both describe Dreros as an ancient city (a Cretan polis with two acropoleis and an agora, as Wikidata also classes it), so the specific type City replaces the generic Archaeological site.", "value_page": null}]'::jsonb),
