    ('f784a924-a2de-42ae-b530-4b292753fa8f'::uuid, 'period_start', '-1500', '-2500', 'fields-wd1-2026-09-26b-s011:f784a924-a2de-42ae-b530-4b292753fa8f:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-1500'' -> ''-2500''', '[{"source": "https://www.english-heritage.org.uk/visit/places/the-sanctuary/history/", "url": "https://www.english-heritage.org.uk/visit/places/the-sanctuary/history/", "quote": "this unique monument was used in the late Neolithic period, and probably built about 2500 BC", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA161488", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA161488", "quote": "BOWL BARROW (Early Bronze Age - 2350 BC to 1501 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0007)", "decision": "replace", "status": "MISSING", "reasoning": "The monuments on Overton Hill begin well before 1500 BC: English Heritage says the Sanctuary on the hill was probably built about 2500 BC and the National Trust heritage record dates the Overton Hill round barrows to the Early Bronze Age, 2350 BC to 1501 BC; both starts lie in the 3000-1500 BC bucket, not 1500-500 BC.", "value_page": null}]'::jsonb),
