    ('f7f2dac5-0f0a-4cbd-8ac0-c2f1f42311ca'::uuid, 'period_start', '-111000', NULL, 'fields-wd1-2026-09-26b-s011:f7f2dac5-0f0a-4cbd-8ac0-c2f1f42311ca:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-clear): ''-111000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0126)", "decision": "clear", "status": "MISSING", "reasoning": "Every source dates the Mousterian occupation only in years before present (e.g. 111,000 BP, 102,000 years old); no source states a BC year, century or millennium, so the start cannot be quoted in a readable form.", "value_page": null}]'::jsonb),
    ('f81ac74d-ecfc-4970-9b11-8a4202305724'::uuid, 'period_name', '500 - 1000 AD', NULL, 'fields-wd1-2026-09-26b-s011:f81ac74d-ecfc-4970-9b11-8a4202305724:period_name', 'fields-wd1-2026-09-26b-s011 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('f81ac74d-ecfc-4970-9b11-8a4202305724'::uuid, 'period_start', '500', NULL, 'fields-wd1-2026-09-26b-s011:f81ac74d-ecfc-4970-9b11-8a4202305724:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-clear): ''500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "clear", "status": "MISSING", "reasoning": "The popular start of c. AD 1000 is only hedged (''may have been established as early as AD 1000'' on Wikipedia, ''believed to date from roughly 1000 AD'' on Ancient Origins), while the only scientific dating (Salvat et al., Journal de la Société des Océanistes) puts the construction of the marae between the mid-17th and 18th centuries, a finding no second independent source reports; no start is securely attested by two sources, and the stored AD 500 predates the settlement of the Society Islands, so the field is emptied.", "value_page": null}]'::jsonb),
    ('f8f6d3e9-c012-4fac-a562-cfbb592a3263'::uuid, 'site_type', 'Megalithic stones', 'Palace', 'fields-wd1-2026-09-26b-s011:f8f6d3e9-c012-4fac-a562-cfbb592a3263:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Megalithic stones'' -> ''Palace''', '[{"source": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2369", "url": "http://odysseus.culture.gr/h/3/eh351.jsp?obj_id=2369", "quote": "The Palace of Knossos. It is the largest of the preserved Minoan palatial centres.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Knossos", "url": "https://en.wikipedia.org/wiki/Knossos", "quote": "The first palace at Knossos was constructed around 1900 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Ministry of Culture and Wikipedia describe the monument as the Palace of Knossos, the largest Minoan palatial centre; it is no set of megalithic stones, and Palace is more specific than the city type of the Wikidata item for Knossos as a whole.", "value_page": null}]'::jsonb),
    ('f9534330-fcf4-4a34-a8ca-6b63fce8362b'::uuid, 'site_type', 'Temple complex', 'Sanctuary', 'fields-wd1-2026-09-26b-s011:f9534330-fcf4-4a34-a8ca-6b63fce8362b:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Temple complex'' -> ''Sanctuary''', '[{"source": "https://en.wikipedia.org/wiki/Shrine_of_Hercules_Curinus", "url": "https://en.wikipedia.org/wiki/Shrine_of_Hercules_Curinus", "quote": "The sanctuary or Shrine of Hercules Curinus was an Italic and later Roman sanctuary", "outcome": "found"}, {"source": "https://turismo.comune.sulmona.aq.it/contenuti/1867751/area-archeologica-santuario-ercole-curino", "url": "https://turismo.comune.sulmona.aq.it/contenuti/1867751/area-archeologica-santuario-ercole-curino", "quote": "Il santuario si sviluppa su due livelli di terrazze artificiali, con la base inferiore costituita da un imponente muro di sostruzione.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0016)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Wikidata item also carries a museum class, but the site is the Italic and Roman terraced sanctuary of Hercules Curinus at Sulmona; both the English Wikipedia article and the Comune di Sulmona call it a sanctuary (santuario), with a temple and sacellum inside it, so Sanctuary is the most specific canonical type and not Temple complex.", "value_page": null}]'::jsonb),
    ('f967e3c4-fc5b-4cd0-91d1-06030d51e31c'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s011:f967e3c4-fc5b-4cd0-91d1-06030d51e31c:period_name', 'fields-wd1-2026-09-26b-s011 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('f967e3c4-fc5b-4cd0-91d1-06030d51e31c'::uuid, 'period_start', '-4500', '-3000', 'fields-wd1-2026-09-26b-s011:f967e3c4-fc5b-4cd0-91d1-06030d51e31c:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-4500'' -> ''-3000''', '[{"source": "https://www.miglus.eu/projects/Tell-Harmal/tell-harmal.html", "url": "https://www.miglus.eu/projects/Tell-Harmal/tell-harmal.html", "quote": "Finally, the expedition executed few deeper soundings and found traces of three or four building levels from the 3rd millennium BC.", "outcome": "found"}, {"source": "https://www.historyfiles.co.uk/KingListsMiddEast/MesopotamiaShaduppum.htm", "url": "https://www.historyfiles.co.uk/KingListsMiddEast/MesopotamiaShaduppum.htm", "quote": "The excavators found seven layers, of which the oldest - VII and VI - are to be dated to the third millennium BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0081)", "decision": "replace", "status": "MISSING", "reasoning": "The excavator Peter Miglus and The History Files both date the oldest building levels of Tell Harmal (Shaduppum) to the 3rd millennium BC (Akkadian period); the stored -4500 lies a bucket too early, so the start becomes the millennium''s first year, -3000.", "value_page": null}]'::jsonb),
    ('f984f67d-95a3-4a2d-9e69-977cfb7a2e4f'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Ain_Harcha', 'https://riunet.upv.es/entities/publication/5cd1c125-94e8-4e3d-b220-57358cc6dfd1', 'fields-wd1-2026-09-26b-s011:f984f67d-95a3-4a2d-9e69-977cfb7a2e4f:source_url', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''https://en.wikipedia.org/wiki/Ain_Harcha'' -> ''https://riunet.upv.es/entities/publication/5cd1c125-94e8-4e3d-b220-57358cc6dfd1''', '[{"source": "https://riunet.upv.es/entities/publication/5cd1c125-94e8-4e3d-b220-57358cc6dfd1", "url": "https://riunet.upv.es/entities/publication/5cd1c125-94e8-4e3d-b220-57358cc6dfd1", "quote": "This study examines the architectural resilience of the Roman temple of Ain Harcha, located in a seismically active zone on the western slope of Mount Hermon in Lebanon.", "outcome": "found"}, {"source": "https://lebanonuntravelled.com/ain-harcha-temple-hermon-mountain/", "url": "https://lebanonuntravelled.com/ain-harcha-temple-hermon-mountain/", "quote": "One fine, well preserved temple is Ain Harcha temple, situated above the village of Ain Harcha.", "outcome": "found"}, {"source": "https://homelandlebanon.com/roman-temples-of-mount-hermon/", "url": "https://homelandlebanon.com/roman-temples-of-mount-hermon/", "quote": "Another well preserved temple of Mount Hermon is located near the village of Ain Hirsha. A 30-minute walk uphill from the village leads to the remains of a Roman temple of the 2nd century A.D.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0091)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the village of Ain Harcha (another Wikidata item), and the temple (Ain Harcha/Ain Hirsha Roman Temple) has no Wikipedia article of its own; the Universitat Politècnica de València repository page of the 2025 HERITAGE paper ''The Case of the Temple of Ain Harcha, Lebanon'' is a scholarly page about the temple itself, and LebanonUntravelled and Homeland Lebanon independently describe the same Roman temple above the village of Ain Harcha/Ain Hirsha.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
