    ('f9ccac76-d1c7-46c4-9c70-4748ce838527'::uuid, 'site_type', 'Archaeological site', 'Forum', 'fields-wd1-2026-09-26b-s011:f9ccac76-d1c7-46c4-9c70-4748ce838527:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Archaeological site'' -> ''Forum''', '[{"source": "https://en.wikipedia.org/wiki/Agora_of_Smyrna", "url": "https://en.wikipedia.org/wiki/Agora_of_Smyrna", "quote": "is an ancient Roman agora located in Smyrna", "outcome": "found"}, {"source": "https://turkish.club/en/attractions/agora-of-smyrna.html", "url": "https://turkish.club/en/attractions/agora-of-smyrna.html", "quote": "The Agora of Smyrna—the forgotten forum of ancient Izmir, just a stone’s throw from the bazaar", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0147)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes the site as the ancient agora of Smyrna and Turkish Club as the forum of ancient Izmir; an agora is the Greek counterpart of the forum, so Forum is more specific than the generic Archaeological site.", "value_page": null}]'::jsonb),
