    ('f9cfcc0f-960a-4184-b72d-ab054ed01221'::uuid, 'period_start', '-5000', '-3700', 'fields-wd1-2026-09-26b-s011:f9cfcc0f-960a-4184-b72d-ab054ed01221:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-5000'' -> ''-3700''', '[{"source": "https://biodiversity.ku.edu/archaeology/research/early-horse-herders", "url": "https://biodiversity.ku.edu/archaeology/research/early-horse-herders", "quote": "Investigations of the Copper Age Botai culture (3700–3100 BCE) of north-central Kazakhstan reveal an unusual economy focused primarily on horses.", "outcome": "found"}, {"source": "https://biodiversity.ku.edu/archaeology/research/early-horse-herders", "url": "https://biodiversity.ku.edu/archaeology/research/early-horse-herders", "quote": "Beginning sometime in the fourth millennium BCE, the Botai radically changed their lifestyle and began settling in substantial, year-round villages. The settlement of Botai had over 160 pit houses, while remote sensing revealed that Krasnyi Yar had 54 and Vasilkovka IV had 44.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Botai_culture", "url": "https://en.wikipedia.org/wiki/Botai_culture", "quote": "The Botai culture is an archaeological culture (c. 3700–3100 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0091)", "decision": "replace", "status": "MISSING", "reasoning": "Krasnyi Yar is a settlement of the Eneolithic Botai culture; the KU Biodiversity Institute (Olsen''s project) dates the culture and its villages, Krasnyi Yar among them, to 3700–3100 BCE, the fourth millennium BCE, as does Wikipedia; the stored -5000 falls a bucket too early, so the start becomes c. 3700 BC.", "value_page": null}]'::jsonb),
    ('f9cfcc0f-960a-4184-b72d-ab054ed01221'::uuid, 'site_type', 'City/town/settlement', 'Village', 'fields-wd1-2026-09-26b-s011:f9cfcc0f-960a-4184-b72d-ab054ed01221:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''City/town/settlement'' -> ''Village''', '[{"source": "https://www.scientificamerican.com/article/horsemen-of-the-steppes-a/", "url": "https://www.scientificamerican.com/article/horsemen-of-the-steppes-a/", "quote": "new research in the ancient Botai village of Krasnyi Yar seems to have turned up some ancient corrals", "outcome": "found"}, {"source": "https://biodiversity.ku.edu/archaeology/research/early-horse-herders", "url": "https://biodiversity.ku.edu/archaeology/research/early-horse-herders", "quote": "the Botai radically changed their lifestyle and began settling in substantial, year-round villages. The settlement of Botai had over 160 pit houses, while remote sensing revealed that Krasnyi Yar had 54 and Vasilkovka IV had 44.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0016)", "decision": "replace", "status": "MISSING", "reasoning": "Krasnyi Yar is an Eneolithic Botai-culture settlement where remote sensing mapped 54 pit houses: Scientific American calls it the ancient Botai village of Krasnyi Yar and the University of Kansas Biodiversity Institute describes the Botai sites as year-round villages of pit houses, so Village is the most specific canonical type, not the broader City/town/settlement.", "value_page": null}]'::jsonb),
