    ('f9e7abcd-b8a2-4844-8145-4a29f19568e2'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s011:f9e7abcd-b8a2-4844-8145-4a29f19568e2:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "clear", "status": "MISSING", "reasoning": "The Danish Nature Agency''s page states the standing-stone grove has never been investigated and is still undated (''bautastenlunden er endnu udateret''); the 1100 BC in Wikipedia and bornholm.net is the general date of the practice of raising standing stones, not of this site, so no two independent sources date its start.", "value_page": null}]'::jsonb),
    ('f9e7abcd-b8a2-4844-8145-4a29f19568e2'::uuid, 'site_type', 'Megalithic stones', 'Standing stone', 'fields-wd1-2026-09-26b-s011:f9e7abcd-b8a2-4844-8145-4a29f19568e2:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Megalithic stones'' -> ''Standing stone''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=15214", "url": "https://www.megalithic.co.uk/article.php?sid=15214", "quote": "Type: Standing Stones", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Louisenlund_(Bornholm)", "url": "https://en.wikipedia.org/wiki/Louisenlund_(Bornholm)", "quote": "Some 50 stones standing upright among the trees, many of them over 2.5 metres (8 ft 2 in) high.", "outcome": "found"}, {"source": "https://udinaturen.dk/facilitet/kulturhistorie/?id=98BFC1EA-9244-4CF9-A5D5-6E82FBC80C82", "url": "https://udinaturen.dk/facilitet/kulturhistorie/?id=98BFC1EA-9244-4CF9-A5D5-6E82FBC80C82", "quote": "I Louisenlund finder man Bornholms næststørste samling af bautasten.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal, Wikipedia and the Danish Nature Agency all describe Louisenlund as a collection of some 50 standing stones (bautasten, menhirs), so the more specific type Standing stone fits better than the generic Megalithic stones.", "value_page": null}]'::jsonb),
