    ('fa2075b9-ae78-4ce0-b00f-673d0139f0ff'::uuid, 'period_start', '1', '1933', 'fields-wd1-2026-09-26b-s011:fa2075b9-ae78-4ce0-b00f-673d0139f0ff:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''1'' -> ''1933''', '[{"source": "https://en.wikipedia.org/wiki/Saguaro_National_Park", "url": "https://en.wikipedia.org/wiki/Saguaro_National_Park", "quote": "Hoover used his power under the Antiquities Act of 1906 to create the monument by proclamation on March 1, 1933.", "outcome": "found"}, {"source": "https://www.nps.gov/sagu/learn/historyculture/index.htm", "url": "https://www.nps.gov/sagu/learn/historyculture/index.htm", "quote": "Herbert Hoover declared this land a National Monument on March 1st, 1933.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0149)", "decision": "replace", "status": "MISSING", "reasoning": "The stored 1 AD is not attested for this site. The sources date the park''s foundation, as Saguaro National Monument, to 1 March 1933 (Wikipedia and the NPS agree); the older human occupation of the land is not a single securely dated start (the NPS itself gives Archaic use from 3500 BCE or perhaps 5000 BC and Hohokam from A.D. 300 or 500 CE, Wikipedia says AD 200), so the securely attested start of the site as a site is its 1933 establishment.", "value_page": null}]'::jsonb),
    ('fa2075b9-ae78-4ce0-b00f-673d0139f0ff'::uuid, 'site_type', 'Petroglyphs', 'Natural feature', 'fields-wd1-2026-09-26b-s011:fa2075b9-ae78-4ce0-b00f-673d0139f0ff:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Petroglyphs'' -> ''Natural feature''', '[{"source": "https://en.wikipedia.org/wiki/Saguaro_National_Park", "url": "https://en.wikipedia.org/wiki/Saguaro_National_Park", "quote": "Saguaro National Park is a national park of the United States in southeastern Arizona", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Saguaro_National_Park", "url": "https://en.wikipedia.org/wiki/Saguaro_National_Park", "quote": "A view of Saguaro National Park''s natural landscape", "outcome": "found"}, {"source": "https://www.nps.gov/articles/nps-geodiversity-atlas-saguaro-national-park-arizona.htm", "url": "https://www.nps.gov/articles/nps-geodiversity-atlas-saguaro-national-park-arizona.htm", "quote": "SAGU was established to preserve and protect giant saguaro cacti, diverse biological communities of the Sonoran Desert, associated mountain ecosystems, and Rincon Creek", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0149)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe Saguaro National Park as a national park preserving the giant saguaro cactus and Sonoran Desert ecosystems, not as a petroglyph site (petroglyphs are only one of its cultural resources); of the canonical types, Natural feature is the one that fits a protected natural area.", "value_page": null}]'::jsonb),
