    ('fa245dcb-9b81-40b2-b221-b670d983549c'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s011:fa245dcb-9b81-40b2-b221-b670d983549c:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "clear", "status": "MISSING", "reasoning": "The Department for Communities calls it a Neolithic passage tomb with a mid-second-millennium BC radiocarbon date for later Bronze Age activity, and Wikipedia says only that it was ''most likely erected before 2000 BC''. No source gives a construction date, and the stored 4000 BC is not attested, so the field is cleared.", "value_page": null}]'::jsonb),
    ('fa245dcb-9b81-40b2-b221-b670d983549c'::uuid, 'site_type', 'Necropolis/tombs complex', 'Tomb', 'fields-wd1-2026-09-26b-s011:fa245dcb-9b81-40b2-b221-b670d983549c:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''Necropolis/tombs complex'' -> ''Tomb''', '[{"source": "https://www.communities-ni.gov.uk/heritage-sites/craigs-dolmen", "url": "https://www.communities-ni.gov.uk/heritage-sites/craigs-dolmen", "quote": "These are clearly the remains of a Neolithic passage tomb", "outcome": "found"}, {"source": "https://causewaycoastandglens.gov.uk/see-do/arts_museums/museums-services/ballymoney-museum/ballymoney-heritage/megalithic-tombs/craigs-dolmen-finvoy", "url": "https://causewaycoastandglens.gov.uk/see-do/arts_museums/museums-services/ballymoney-museum/ballymoney-heritage/megalithic-tombs/craigs-dolmen-finvoy", "quote": "It is a passage tomb, consisting of a single oval chamber, formed by upright stones which support a capstone.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "replace", "status": "CONFLICT", "reasoning": "The state-care record (DfC) and Causeway Coast and Glens Borough Council both describe a single passage tomb, not a complex of tombs; Wikipedia adds that it is wrongly called a dolmen, so Tomb is the most specific canonical type that holds.", "value_page": null}]'::jsonb),
