    ('fadd9ef3-4d6a-4a8b-8b2a-250388ee531d'::uuid, 'period_start', '-1500', '-1600', 'fields-wd1-2026-09-26b-s011:fadd9ef3-4d6a-4a8b-8b2a-250388ee531d:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-1500'' -> ''-1600''', '[{"source": "https://www.schule-bw.de/faecher-und-schularten/gesellschaftswissenschaftliche-und-philosophische-faecher/landeskunde-landesgeschichte/module/epochen/fruehgeschichte/kelten/heuneburg/12zeittafel.htm", "url": "https://www.schule-bw.de/faecher-und-schularten/gesellschaftswissenschaftliche-und-philosophische-faecher/landeskunde-landesgeschichte/module/epochen/fruehgeschichte/kelten/heuneburg/12zeittafel.htm", "quote": "eine erste Befestigung mit Wall und Graben folgt in der mittleren Bronzezeit (16. - 13. Jahrhundert v. Chr.)", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Heuneburg", "url": "https://de.wikipedia.org/wiki/Heuneburg", "quote": "belegen eine Besiedlung nachweislich seit der mittleren Bronzezeit (16.–13. Jahrhundert v. Chr.)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "MISSING", "reasoning": "The Baden-Württemberg education server and German Wikipedia (summarising the 1950-1979 excavations) date the first settlement and fortification of the plateau to the Middle Bronze Age, 16th-13th century BC; Neolithic finds are isolated stray finds. The start, the 16th century BC (-1600), lies in the 3000 - 1500 BC bucket, not the stored one.", "value_page": null}]'::jsonb),
