    ('fce870cc-5856-4801-80e9-2b7a9ef96b1c'::uuid, 'period_start', '500', '-800', 'fields-wd1-2026-09-26b-s011:fce870cc-5856-4801-80e9-2b7a9ef96b1c:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''500'' -> ''-800''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=16556", "url": "https://www.megalithic.co.uk/article.php?sid=16556", "quote": "A key old Maya city dating from the Middle Preclassic period (800 - 400 BCE).", "outcome": "found"}, {"source": "https://www.themayanruinswebsite.com/yaxuna.html", "url": "https://www.themayanruinswebsite.com/yaxuna.html", "quote": "It has a long settlement history that spans from the Middle Preclassic (750-350 BCE) through the Post Classic (1150-1521 CE).", "outcome": "found"}, {"source": "https://www.mexicodesconocido.com.mx/yaxunah.html", "url": "https://www.mexicodesconocido.com.mx/yaxunah.html", "quote": "los vestigios más antiguos de Yaxunah datan del Preclásico Medio (alrededor del 600 a.C.).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0098)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal dates Yaxuna''s beginnings to the Middle Preclassic, 800 BCE, the Mayan Ruins Website its settlement history from 750 BCE and Mexico Desconocido its oldest remains to about 600 BC, all in the 1500-500 BC bucket and consistent with Wikipedia''s occupation from the Middle Formative; the stored 500 AD (the Late Classic Coba period) is far too late.", "value_page": null}]'::jsonb),
