    ('fd79f148-d931-42c7-8883-41732a93d209'::uuid, 'period_start', '1', '700', 'fields-wd1-2026-09-26b-s011:fd79f148-d931-42c7-8883-41732a93d209:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''1'' -> ''700''', '[{"source": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=12010", "url": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=12010", "quote": "Cronológicamente, la ocupación de Marayniyoq se inicia alrededor de los 700 DC y continua hasta los 1000 DC.", "outcome": "found"}, {"source": "https://archive.org/stream/ai-0502/AI0502_djvu.txt", "url": "https://archive.org/stream/ai-0502/AI0502_djvu.txt", "quote": "A series of radiocarbon dates for the various contexts associated with the compact floor and the broken large sized vessels range between AD 780 and 900", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0111)", "decision": "replace", "status": "MISSING", "reasoning": "Peru''s MINCETUR inventory dates the start of occupation at Marayniyoq to around AD 700, and the excavators (Valdez, Bettcher and Valdez 2010) report radiocarbon dates of AD 780-900 for its main contexts; the start lies in the 500 - 1000 AD bucket, not in 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('fd79f148-d931-42c7-8883-41732a93d209'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'fields-wd1-2026-09-26b-s011:fd79f148-d931-42c7-8883-41732a93d209:site_type', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''City/town/settlement'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Marayniyoq", "url": "https://en.wikipedia.org/wiki/Marayniyoq", "quote": "is an archaeological site in the region of Ayacucho in Peru", "outcome": "found"}, {"source": "https://revistas.pucp.edu.pe/index.php/boletindearqueologia/article/view/2242/0", "url": "https://revistas.pucp.edu.pe/index.php/boletindearqueologia/article/view/2242/0", "quote": "En este trabajo se dan a conocer los resultados de las excavaciones efectuadas en Marayniyoq, un centro especializado wari del valle de Ayacucho.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0111)", "decision": "replace", "status": "MISSING", "reasoning": "No source calls Marayniyoq a town or settlement: the excavators describe a specialised Wari facility for grinding maize and brewing chicha, which no specific canonical type covers, and Wikipedia and MINCETUR list it simply as an archaeological site, so the generic type replaces City/town/settlement.", "value_page": null}]'::jsonb),
