    ('ff53d37c-ab2b-4874-8ed8-a3336ccd12fc'::uuid, 'period_start', '-3000', '-1300', 'fields-wd1-2026-09-26b-s011:ff53d37c-ab2b-4874-8ed8-a3336ccd12fc:period_start', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''-3000'' -> ''-1300''', '[{"source": "http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=15961", "url": "http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=15961", "quote": "Χρονολογείται στην Υστερομινωική ΙΙΙ Β περίοδο (13ος αι. π. Χ.).", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Maleme", "url": "https://en.wikipedia.org/wiki/Maleme", "quote": "It dates back to the Late Minoan III A-B era (14th-13th c. B.C.).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "replace", "status": "MISSING", "reasoning": "The Greek Ministry of Culture dates the tholos tomb to Late Minoan IIIB, the 13th century BC. Wikipedia gives Late Minoan IIIA-B, the 14th-13th century BC. The stored -3000 (Early Minoan) is wrong; the tomb''s construction belongs to the 13th century BC, in the 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
