    ('ff53d37c-ab2b-4874-8ed8-a3336ccd12fc'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Maleme', 'http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=15961', 'fields-wd1-2026-09-26b-s011:ff53d37c-ab2b-4874-8ed8-a3336ccd12fc:source_url', 'fields-wd1-2026-09-26b-s011 (wd1-replace): ''https://en.wikipedia.org/wiki/Maleme'' -> ''http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=15961''', '[{"source": "http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=15961", "url": "http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=15961", "quote": "Ο θολωτός τάφος στο Μάλεμε βρίσκεται 17 χιλιόμετρα δυτικά της πόλης των Χανίων", "outcome": "found"}, {"source": "https://topostext.org/place/354247XMal", "url": "https://topostext.org/place/354247XMal", "quote": "Mycenaean tholos tomb at Maleme WWII military cemetery", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about Maleme village. The Greek Ministry of Culture''s Odysseus page is about the tholos tomb itself, and ToposText names the same tomb. No Wikipedia article on the tomb exists.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
